  const draw = () => { if (i >= deck.length) { z.innerHTML = `<div class="card stack">${gBack(z)}<div class="fb ${sc >= 5 ? "ok" : "bad"}"><b>${sc}/${deck.length}</b> solved.</div><button class="btn sm" id="gr">Play again</button></div>`; return; } const d = deck[i], opts = shuffle([d[1], ...d[2]]); z.innerHTML = `<div class="card stack">${gBack(z)}<div class="row between"><div class="label">Adverse Effect Detective</div><span class="xs muted">${i + 1}/${deck.length}</span></div><p class="lead">Finding: <b>${esc(d[0])}</b></p><p class="small">Which medication is most likely responsible?</p><div class="stack">${opts.map(o => `<button class="opt" data-a="${esc(o)}"><span class="mk"></span><span>${esc(o)}</span></button>`).join("")}</div><div id="gf" aria-live="polite"></div></div>`; };
