  const draw = () => { if (i >= deck.length) { z.innerHTML = `<div class="card stack">${gBack(z)}<div class="fb ${sc >= 7 ? "ok" : "bad"}"><b>${sc}/${deck.length}</b> correct.</div><button class="btn sm" id="gr">Play again</button></div>`; return; } z.innerHTML = `<div class="card stack">${gBack(z)}<div class="row between"><div class="label">Expected or dangerous?</div><span class="xs muted">${i + 1}/${deck.length}</span></div><p class="lead">${esc(deck[i][0])}</p><div class="stack">${Object.entries(L).map(([k, n]) => `<button class="opt" data-a="${k}"><span class="mk"></span><span>${n}</span></button>`).join("")}</div><div id="gf" aria-live="polite"></div></div>`; };
