/* ---------- 75-question mock ---------- */
let LQ_PENDING = false;
function rvMock(z) {
  const s = lqS(), paused = S.resume && S.resume.key === "lqmock" ? S.resume : null, other = S.resume && S.resume.key !== "lqmock";
  z.innerHTML = `<div class="card stack"><div class="head"><span class="label">Advanced Pharmacology HESI Mock · 75 questions</span><h2 class="h3">Exam conditions</h2><p class="small muted">Covers classes, adverse effects, toxicity, renal/liver monitoring, interactions, insulin, thyroid, respiratory, administration, teaching and prioritization. No answers or rationales until you submit; previous attempts are kept; an unfinished attempt is saved after every answer. Practice tool — it does not predict your HESI score.</p></div>
   ${paused ? `<div class="panel row between"><span class="small"><b>Unfinished mock saved</b> · question ${Math.min(paused.i + 1, paused.n)} of ${paused.n}</span><button class="btn sm primary" id="mkRes">Resume</button></div>` : ""}
   ${other ? `<p class="xs muted">You have a paused practice exam elsewhere — this mock won't save mid-way so that exam isn't overwritten.</p>` : ""}
   <button class="btn ${paused ? "" : "primary"}" id="mkGo">${s.mock.length || paused ? "Start a new attempt" : "Start the mock exam"}</button>
   ${s.mock.length ? `<div class="stack"><div class="label">Previous attempts</div>${s.mock.slice(-8).reverse().map(m => `<div class="row between small"><span>${fmtDate(m.t)}</span><span class="mono"><b>${m.score}%</b> · first attempts ${m.fa ? pct(m.fac, m.fa) + "%" : "—"}</span></div>`).join("")}</div>` : ""}</div><div id="mkz"></div>`;
  $("#mkGo", z).onclick = () => startMock(z, null, !other);
  const r = $("#mkRes", z); if (r) r.onclick = () => startMock(z, paused, true);
  if (LQ_PENDING && paused) { LQ_PENDING = false; startMock(z, paused, true); }
}
function startMock(z, resumeState, keep) {
  const s = lqS(), box = $("#mkz", z);
  const items = resumeState ? null : shuffle(LQ_MOCK_IDS.map(id => QBYID[id]).filter(Boolean));
  Quiz(box, { items, mode: "exam", conf: false, title: "Pharm HESI Mock", resumeKey: keep ? "lqmock" : undefined, resumeState, again: () => route(), onDone: (r, its) => {
    const by = {}; its.forEach(x => qTags(x.q).slice(0, 2).forEach(g => { by[g] = by[g] || [0, 0]; by[g][1]++; if (x.ok) by[g][0]++; }));
    s.mock.push({ t: Date.now(), score: r.score, n: r.n, fa: r.fa, fac: r.fac, by }); s.mock = s.mock.slice(-20); save();
    const weak = Object.entries(by).filter(([g, v]) => v[0] / v[1] < .8).sort((a, b) => a[1][0] / a[1][1] - b[1][0] / b[1][1]);
    setTimeout(() => { if (!box.isConnected) return; box.insertAdjacentHTML("afterbegin", `<div class="card stack" id="mkrem"><div class="label">Targeted remediation</div>${weak.length ? weak.map(([g, v]) => `<div class="row between small"><span>${esc(TAGN[g] || g)}</span><span class="mono">${v[0]}/${v[1]}</span></div>`).join("") + `<div class="row">${[...new Set(weak.map(([g]) => ({ ace: "ace", renal: "labs", labs: "labs", inhaler: "inh", insulin: "ins", thyroid: "thy", herbal: "herb", interactions: "herb" })[g]).filter(Boolean))].map(k => `<button class="btn sm" data-rm="${k}">Review: ${esc(RV_TABS.find(t => t[0] === k)[1])}</button>`).join("")}<button class="btn sm primary" data-rm="weak">Practice my weak areas</button></div>` : `<div class="small">All topics at 80% or better on this attempt.</div>`}</div>`); $("#mkrem", box).onclick = e => { const b = e.target.closest("[data-rm]"); if (b) go("review", b.dataset.rm); }; }, 0);
  } });
  box.scrollIntoView({ behavior: "smooth", block: "start" });
}

/* ---------- Weak areas ---------- */
function rvWeak(z) {
  const t = tagStats(), rows = Object.entries(t).sort((a, b) => (a[1].att ? a[1].cor / a[1].att : 2) - (b[1].att ? b[1].cor / b[1].att : 2));
  z.innerHTML = `<div class="card stack"><div class="head"><span class="label">My pharm weak areas</span><h2 class="h3">Where to spend your next study block</h2><p class="small muted">Based on every review and insulin question you've answered. Mastered questions (right every time, at least twice) are skipped in quick reviews.</p></div>
   <div class="row"><button class="btn primary" data-qr="5">5-min review</button><button class="btn" data-qr="10">10-min</button><button class="btn" data-qr="20">20-min</button></div>
   <div class="tbl" tabindex="0" role="region" aria-label="Performance by topic"><table><thead><tr><th scope="col">Topic</th><th scope="col">Seen</th><th scope="col">First-attempt</th><th scope="col">All attempts</th><th scope="col">Open misses</th><th scope="col"><span class="sr">Action</span></th></tr></thead><tbody>${rows.map(([g, x]) => `<tr><th scope="row">${esc(TAGN[g] || g)}</th><td>${x.seen}/${x.n}</td><td>${x.fa ? pct(x.fac, x.fa) + "%" : "—"}</td><td>${x.att ? pct(x.cor, x.att) + "%" : "—"}</td><td>${x.miss}</td><td><button class="btn sm" data-tg="${g}">Practice</button></td></tr>`).join("")}</tbody></table></div></div><div id="wkz"></div>`;
  z.onclick = e => { const q = e.target.closest("[data-qr]"); if (q) return rvQuiz($("#wkz", z), quickPool({ 5: 6, 10: 12, 20: 24 }[q.dataset.qr]), `${q.dataset.qr}-minute review`); const b = e.target.closest("[data-tg]"); if (b) rvQuiz($("#wkz", z), tagItems([b.dataset.tg], 6), TAGN[b.dataset.tg] || b.dataset.tg); };
}

/* ---------- Reports ---------- */
function rvAudit(z) {
  const added = DRUGS.filter(d => LQ_EMPH[d.id] && d.src && (d.src[0] === "LQ" || d.src[0] === "LQL") || ["methimazole"].includes(d.id));
  z.innerHTML = `<div class="card stack"><div class="head"><span class="label">Source-to-app coverage audit</span><h2 class="h3">Every slide and lecture topic, checked against the app</h2><p class="small muted">“Existing coverage” describes the app before this update.</p></div>
   <div class="tbl" tabindex="0" role="region" aria-label="Coverage audit table"><table><thead><tr><th scope="col">Source</th><th scope="col">Topic</th><th scope="col">Existing coverage</th><th scope="col">Action taken</th><th scope="col">Status</th></tr></thead><tbody>${LQ_AUDIT.map(r => `<tr><th scope="row">${esc(r[0])}</th>${r.slice(1).map(c => `<td>${esc(c)}</td>`).join("")}</tr>`).join("")}</tbody></table></div></div>
   <div class="card stack"><div class="label">Medication gap report — ${added.length} profiles added</div><div class="pills">${added.map(d => `<a class="pill" href="#library/${d.id}">${esc(d.g)}</a>`).join("")}</div><p class="xs muted">Herbal supplements are taught in the Herbals module rather than as drug profiles. Existing profiles were not duplicated; ${Object.keys(LQ_EMPH).length} profiles now carry instructor emphasis, immediate-follow-up signs and clinical-judgment notes.</p></div>
   <div class="card stack"><div class="label">Question bank report</div><div class="small">Added <b>${LQ_Q.length}</b> original review questions (${LQ_Q.filter(q => q.fmt === "sata").length} select-all, ${LQ_Q.filter(q => q.fmt === "order").length} ordering, rest single-best-answer), every one with a rationale and per-option explanations. Revised: lisinopril, donepezil, tamsulosin, vancomycin, glargine fields used by generated questions. The 75-question mock is a fixed form drawn from these items.</div></div>`;
}
function rvAcc(z) {
  z.innerHTML = `<div class="card stack"><div class="head"><span class="label">Clinical accuracy report</span><h2 class="h3">${LQ_DISC.length} statements corrected or clarified</h2><p class="small muted">Instructor emphasis is kept; what's changed is the clinical content, with sources. Never memorize a statement just because it's on a slide.</p></div>
   ${LQ_DISC.map(d => `<div class="updbox"><div class="label">${esc(d.t)}</div><div class="upd-grid"><div><b>Original statement</b><p class="small">${esc(d.o)}</p><p class="xs muted">${esc(d.s)}</p></div><div><b>Verified interpretation</b><p class="small">${esc(d.v)}</p><p class="xs">${(d.r || []).map(refA).filter(Boolean).join(" · ") || "Verified against the instructor's own slide and standard references."}</p></div><div><b>Why it needed review · what changed in the app</b><p class="small">${esc(d.w)}</p><p class="xs">${esc(d.c)}</p></div></div></div>`).join("")}</div>`;
}
